-- goauth:statement
CREATE TABLE `email_change_requests` (`user_id` varchar(36) NOT NULL, `id` varchar(36) NOT NULL, `session_id` varchar(36) NOT NULL, `scope` varchar(10) NOT NULL, `current_email` varchar(255) NOT NULL, `new_email` varchar(255) NOT NULL, `current_code_hash` varchar(64) NOT NULL, `new_code_hash` varchar(64) NOT NULL, `identity_hash` varchar(64) NOT NULL, `status` varchar(16) NOT NULL, `created_at` bigint NOT NULL, `expires_at` bigint NOT NULL, `budget_started_at` bigint NOT NULL, `current_sent_at` bigint NOT NULL, `new_sent_at` bigint NOT NULL, `starts` int NOT NULL, `attempts` int NOT NULL, `current_resends` int NOT NULL, `new_resends` int NOT NULL, PRIMARY KEY (`user_id`), CONSTRAINT `email_change_requests_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON UPDATE NO ACTION ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;

